    m=re.search(r'^\[(\d{4}-\d{2}-\d{2})T.*?(?:run \S+ done in [^:]*: \d+ read|done: \d+ cases), (\d+) changed',line)
    if m:
        d=m.group(1); runs[d]+=1; ch[d]+=int(m.group(2))
    v=re.search(r'^\[(\d{4}-\d{2}-\d{2})T.*case-cost-sync (\S+),',line)
    if v: ver.setdefault(v.group(1),set()).add(v.group(2))
for d in sorted(runs): print(d, runs[d], 'changed', ch[d], 'avg/run', round(ch[d]/runs[d],1), ver.get(d))
EOF

